import{r as n,o as i,a as o,b as e,d as r,F as s,c as d,e as t}from"./app.756eaed4.js";import{_ as l}from"./plugin-vue_export-helper.21dcd24c.js";const c={},h=d('<h1 id="release-notes" tabindex="-1"><a class="header-anchor" href="#release-notes" aria-hidden="true">#</a> Release notes</h1><h2 id="ibm-ims-explorer-for-vs-code" tabindex="-1"><a class="header-anchor" href="#ibm-ims-explorer-for-vs-code" aria-hidden="true">#</a> IBM IMS Explorer for VS Code</h2><p>This document provides a summary of notable changes, enhancements, and fixes for each release of the IBM IMS Explorer for VS Code extension.</p><h2 id="release-history" tabindex="-1"><a class="header-anchor" href="#release-history" aria-hidden="true">#</a> Release history</h2><table><thead><tr><th>Version</th><th>Release date</th><th>Notes</th></tr></thead><tbody><tr><td><a href="#version-1-2-0">1.2.0</a></td><td>August 28, 2026</td><td><strong>Enhancements</strong><br>\u2022 Welcome page on first launch<br>\u2022 IMS type-1/type-2 command execution with return codes, table/detail views, history, and JSON download<br>\u2022 SSL certificate management for database connection profiles<br>\u2022 MFA/TOTP prompt support during database connections<br>\u2022 Reconnect prompt when modifying an active connection<br>Support has been added for the following:<br>\u2022 Add/edit segment fields from the field table view<br>\u2022 Move/delete one or more fields from a segment<br>\u2022 User-defined type converters and UDB driver versions via custom JAR<br>\u2022 IMS catalog and local project metadata as <code>metadataSource</code><br>\u2022 Advanced search (Find referenced PSBs/DBDs) in DBD and PSB table views<br>\u2022 Additional field data columns in catalog DBD/PSB table views</td></tr><tr><td><a href="#version-1-1-0">1.1.0</a></td><td>April 28, 2026</td><td><strong>Enhancements</strong><br>\u2022 Import DBDs/PSBs from the IMS catalog into IMS projects<br>\u2022 Edit DDL and source code within IMS projects<br>\u2022 Interactive hierarchical visualization of DBDs and PSBs<br>\u2022 SQL editor: CodeLens for connection selection, per-file connections, and Run button<br>\u2022 <code>showIMSCatalogs</code> property to hide system catalog DBDs/PSBs by default<br>\u2022 MFA support and intelligent re-authentication prompts<br>\u2022 Unified logging output channel<br>\u2022 Text labels in tabs for improved UI clarity<br><br><strong>Fixes</strong><br>\u2022 Quick Pick option to re-enter credentials on authentication failure (TS021433816)<br>\u2022 Security vulnerability patches</td></tr><tr><td><a href="#version-1-0-0-initial-release">1.0.0</a></td><td>January 30, 2026</td><td><strong>Enhancements</strong><br>\u2022 Initial release with integrated IMS database development in VS Code<br>Support has been added for the following:<br>\u2022 Creating and managing IMS projects, driver definitions, and connections<br>\u2022 Browsing IMS Catalog and IMS databases<br>\u2022 Tree and table views for DBDs, PSBs, PCBs, segments, and fields<br>\u2022 Viewing DBD source, DDL, and database metadata<br>\u2022 Executing SQL queries with tabular results and query history<br>\u2022 CSV export of SQL query results</td></tr></tbody></table><h2 id="release-notes-1" tabindex="-1"><a class="header-anchor" href="#release-notes-1" aria-hidden="true">#</a> Release notes</h2><h3 id="version-1-2-0" tabindex="-1"><a class="header-anchor" href="#version-1-2-0" aria-hidden="true">#</a> Version 1.2.0</h3><p>This version includes the following enhancements:</p><ul><li>Added a welcome page that loads on first launch, providing quick-start scenarios to verify installation and prepare the first project workspace.</li><li>Added support for executing IMS type-1 and type-2 commands from IMS projects. A <strong>Commands</strong> folder can be added to IMS projects where commands can be created and executed against an IMS connection. Results include a return code, table view, and detailed view, which can be downloaded as a JSON file. A command history view retains previous results.</li><li>Added SSL certificate management attributes for database connection profiles in <code>ims.connections.json</code>.</li><li>Added support for multi-factor authentication (MFA) prompts during database connections. When connecting to an IMS database that uses MFA or TOTP, users are prompted to provide a token before the connection is established.</li><li>Added reconnect support when modifying an active IMS connection. A notification is provided to re-establish the connection.</li><li>Added the ability to add and edit segment fields from the field table view. A custom JAR can be configured to support user-defined type converters and UDB driver versions.</li><li>Added the ability to move or delete one or more fields from a segment in the field table view.</li><li>Added advanced search options to the DBD and PSB table views. Select the overflow menu for a DBD or PSB to use <strong>Find referenced PSBs</strong> or <strong>Find referenced DBDs</strong>.</li><li>Added support for using IMS catalog and local project metadata as the <code>metadataSource</code> for a database profile.</li><li>Added additional field data columns to the catalog DBD and PSB table views.</li></ul><h3 id="version-1-1-0" tabindex="-1"><a class="header-anchor" href="#version-1-1-0" aria-hidden="true">#</a> Version 1.1.0</h3><p>This version includes the following enhancements:</p><ul><li>Added the ability to import DBDs and PSBs from the IMS catalog into IMS projects.</li><li>Added support for editing DDL and source code within IMS projects.</li><li>Added interactive hierarchical visualization of DBDs and PSBs for IMS database connections and IMS projects.</li><li>Enhanced SQL editor with CodeLens for connection selection, per-file connections, and Run button in title bar.</li><li>Added <code>showIMSCatalogs</code> configuration property to hide system catalog DBDs and PSBs (DFSC prefix) by default.</li><li>Improved credential handling with Multi-Factor Authentication (MFA) support and intelligent re-authentication prompts.</li><li>Added unified logging output channel for frontend and backend logs.</li><li>Updated UI with text labels in tabs for improved clarity.</li></ul><p>This version includes the following fixes:</p><ul><li>Fix for case TS021433816: Quick Pick option now provided to re-enter credentials when authentication failures occur.</li><li>Addressed various security vulnerabilities.</li></ul><h3 id="version-1-0-0-initial-release" tabindex="-1"><a class="header-anchor" href="#version-1-0-0-initial-release" aria-hidden="true">#</a> Version 1.0.0 - Initial release</h3><p>This version includes the following enhancements:</p><ul><li>Integrated IMS database development experience inside Visual Studio Code.</li><li>Support for creating and managing IMS projects, driver definitions, and database connections.</li><li>Ability to connect to IMS Catalog and browse IMS databases.</li><li>Tree and table views for DBDs, PSBs, PCBs, segments, and fields.</li><li>Viewing of DBD source, DDL, and database metadata.</li><li>Execution of SQL queries against IMS databases with tabular results and query history.</li><li>CSV export of SQL query results.</li></ul><h2 id="note" tabindex="-1"><a class="header-anchor" href="#note" aria-hidden="true">#</a> Note</h2>',18),u=t("Issues and enhancement requests for any features listed can be submitted through the project "),p={href:"https://github.com/IBM/ims-explorer-about/issues",target:"_blank",rel:"noopener noreferrer"},f=t("GitHub repository"),b=t(".");function m(g,S){const a=n("ExternalLinkIcon");return i(),o(s,null,[h,e("ul",null,[e("li",null,[u,e("a",p,[f,r(a)]),b])])],64)}var D=l(c,[["render",m]]);export{D as default};
